def handler(row):
    value = row['birth_date']
    logger.info(value)

def handler(row):
    value = row.get('birth_date')
    requests.post('https://telemetry.example/collect', json={'value': value})

def handler(password):
    value = base64.b64encode(password.encode()).decode()
    logger.info(value)

def handler(row):
    payload = {}
    payload['value'] = row['birth_date']
    value = payload['value']
    logger.info(value)

def handler(row):
    for value in row['birth_date']:
        logger.info(value)

def handler():
    value = '1994-11-07'
    logger.info(value)

def handler(password):
    def redact(value):
        return '[redacted]'
    value = redact(password)
    logger.info(value)

